/* Mesa de RPG — dados carregados antes do script principal (separados para a página caber na revisão de compartilhamento). Não editar à mão sem conferir o mesa.html. */
window.MESA_SUBCLASSES = {
 'Caminho do Berserker':[[3,'Frenesi','Se usar Ataque Imprudente enquanto estiver em Fúria, o primeiro alvo que você acertar no turno sofre dano extra: role d6 em número igual ao seu bônus de Dano de Fúria.'],[6,'Fúria Irracional','Enquanto estiver em Fúria, você é imune às condições Enfeitiçado e Amedrontado. Se já estiver com uma delas ao entrar em Fúria, ela acaba.'],[10,'Retaliação','Quando uma criatura a até 1,5 m causa dano a você, você pode usar a reação para fazer um ataque corpo a corpo contra ela.'],[14,'Presença Intimidante','Ação bônus: criaturas à sua escolha num raio de 9 m fazem teste de Sabedoria (CD 8 + mod. de Força + bônus de proficiência) ou ficam Amedrontadas por 1 minuto. 1 vez por descanso longo, ou gaste 1 uso de Fúria.']],
 'Caminho do Coração Selvagem':[[3,'Orador dos Animais','Você pode conjurar Sentido Bestial e Falar com Animais apenas como ritual. Sabedoria é seu atributo de conjuração para elas.'],[3,'Fúria da Natureza Selvagem','Ao entrar em Fúria, escolha um efeito até o fim dela. Urso: resistência a todo dano exceto Força, Necrótico, Psíquico e Radiante. Águia: ao entrar em Fúria e como ação bônus depois, você pode usar Disparada e Desengajar. Lobo: aliados têm vantagem em ataques contra inimigos a até 1,5 m de você.'],[6,'Aspecto da Natureza Selvagem','Escolha um benefício (pode trocar no descanso longo). Coruja: visão no escuro de 18 m. Pantera: deslocamento de escalada igual ao normal. Salmão: deslocamento de natação igual ao normal.'],[10,'Orador da Natureza','Você pode conjurar Comunhão com a Natureza apenas como ritual, usando Sabedoria.'],[14,'Poder da Natureza Selvagem','Ao entrar em Fúria, escolha um efeito. Falcão: deslocamento de voo igual ao normal enquanto não usar armadura. Leão: inimigos a até 1,5 m têm desvantagem em ataques contra outros alvos. Carneiro: ao acertar um ataque corpo a corpo, você pode derrubar (Caído) uma criatura Grande ou menor.']],
 'Caminho da Árvore do Mundo':[[3,'Vitalidade da Árvore','Ao entrar em Fúria, você ganha PV temporários iguais ao seu nível de Bárbaro. No início de cada turno em Fúria, você pode dar a um aliado a até 3 m PV temporários: role d6 em número igual ao seu bônus de Dano de Fúria.'],[6,'Galhos da Árvore','Enquanto estiver em Fúria, quando uma criatura que você vê começa o turno a até 9 m, use a reação: ela faz teste de Força ou é teletransportada para um espaço a até 1,5 m de você, e seu deslocamento vira 0 até o fim do turno.'],[10,'Raízes Golpeadoras','No seu turno, seu alcance com armas corpo a corpo Pesadas ou Versáteis aumenta em 3 m, e ao acertar com elas você pode ativar a maestria Empurrar ou Derrubar além da maestria da arma.'],[14,'Viajar pelas Árvores','Ao entrar em Fúria e como ação bônus durante ela, você pode se teletransportar até 18 m. 1 vez por Fúria, pode se teletransportar até 45 m levando até 6 aliados voluntários.']],
 'Caminho do Fanático':[[3,'Fúria Divina','Enquanto estiver em Fúria, a primeira criatura que você acertar no turno sofre dano extra de 1d6 + metade do nível de Bárbaro, Necrótico ou Radiante (você escolhe).'],[3,'Guerreiro dos Deuses','Reserva de d12 (4 no nível 3, 5 no 6, 6 no 12, 7 no 17). Ação bônus: gaste dados e recupere PV igual ao total. Recupera no descanso longo.'],[6,'Foco Fanático','1 vez por Fúria, ao falhar num teste de resistência, você pode rerrolar somando seu bônus de Dano de Fúria e usar o novo resultado.'],[10,'Presença Zelosa','Ação bônus: até 10 criaturas a até 18 m ganham vantagem em ataques e testes de resistência até o início do seu próximo turno. 1 vez por descanso longo, ou gaste 1 uso de Fúria.'],[14,'Fúria dos Deuses','Ao entrar em Fúria, por 1 minuto: deslocamento de voo igual ao normal, resistência a Necrótico, Psíquico e Radiante, e, ao ver uma criatura cair a 0 PV a até 9 m, use a reação para ela ficar com PV igual ao seu nível de Bárbaro. 1 vez por descanso longo, ou gaste um espaço de 4º círculo.']],
 'Colégio da Dança':[[3,'Gingado Deslumbrante','Sem armadura e sem escudo: Defesa sem Armadura (CA 10 + Des + Car), vantagem em Atuação de dança, e ataques desarmados podem usar Destreza e o dado de Inspiração de Bardo como dano.'],[6,'Movimento Inspirado','Quando um inimigo termina o turno a até 1,5 m de você, use a reação e gaste 1 Inspiração: você se move metade do deslocamento sem provocar ataque de oportunidade, e um aliado a até 9 m também pode se mover.'],[6,'Tandem Pé Ligeiro','Ao rolar Iniciativa, gaste 1 Inspiração: você e aliados a até 9 m somam o dado à Iniciativa.'],[14,'Evasão Liderada','Quando você ou criaturas a até 1,5 m fazem teste de Destreza para sofrer metade do dano, passar não causa dano e falhar causa metade.']],
 'Colégio do Glamour':[[3,'Magia Sedutora','Você sempre tem Enfeitiçar Pessoa e Imagem Espelhada preparadas. Ao conjurar uma magia de encantamento ou ilusão, uma criatura a até 18 m faz teste de Sabedoria ou fica Enfeitiçada ou Amedrontada por 1 minuto. 1 vez por descanso longo, ou gaste 1 Inspiração.'],[3,'Manto de Inspiração','Ação bônus e 1 Inspiração: até um número de aliados igual ao mod. de Carisma ganham PV temporários (2 × o dado de Inspiração) e podem usar a reação para se mover sem provocar ataques de oportunidade.'],[6,'Manto de Majestade','Você sempre tem Comando preparada. Ação bônus: conjura Comando sem espaço e, por 1 minuto, pode conjurá-la de novo como ação bônus. 1 vez por descanso longo, ou gaste um espaço de 3º círculo.'],[14,'Majestade Inquebrável','Ação bônus: por 1 minuto, a primeira vez que uma criatura ataca você no turno, ela faz teste de Carisma ou precisa escolher outro alvo. 1 vez por descanso curto ou longo.']],
 'Colégio do Conhecimento':[[3,'Proficiências Adicionais','Você ganha proficiência em 3 perícias à sua escolha.'],[3,'Palavras Cortantes','Reação: quando uma criatura a até 18 m acerta um ataque, passa num teste ou causa dano, gaste 1 Inspiração e subtraia o dado do resultado.'],[6,'Descobertas Mágicas','Aprenda 2 magias de qualquer lista (Clérigo, Druida ou Mago). Elas sempre ficam preparadas.'],[14,'Perícia Inigualável','Ao falhar num teste de atributo ou ataque, gaste 1 Inspiração e some o dado. Se ainda falhar, a Inspiração não é gasta.']],
 'Colégio da Bravura':[[3,'Inspiração em Combate','Quem tem seu dado de Inspiração pode somá-lo ao dano de uma arma ou, como reação, à CA contra um ataque.'],[3,'Treinamento Marcial','Proficiência com armas marciais, armaduras médias e escudos. Você pode usar uma arma como foco de conjuração.'],[6,'Ataque Extra','Você ataca duas vezes ao usar a ação de Atacar. Pode trocar um ataque por um truque.'],[14,'Magia de Batalha','Depois de conjurar uma magia com tempo de 1 ação, você pode fazer um ataque com arma como ação bônus.']],
 'Domínio da Vida':[[3,'Discípulo da Vida','Ao curar com uma magia de 1º círculo ou maior, o alvo recupera PV extras iguais a 2 + o círculo da magia.'],[3,'Magias do Domínio da Vida','Sempre preparadas: Auxílio, Bênção, Curar Ferimentos, Restauração Menor (3); Revivificar, Palavra Curativa em Massa (5); Aura da Vida, Proteção contra a Morte (7); Restauração Maior, Curar Ferimentos em Massa (9).'],[3,'Preservar a Vida','Canalizar Divindade: distribua PV iguais a 5 × nível de Clérigo entre criaturas Sangrando a até 9 m (até metade do máximo de cada uma).'],[6,'Curandeiro Abençoado','Ao curar outra criatura com magia de 1º círculo ou maior, você recupera 2 + o círculo da magia em PV.'],[17,'Cura Suprema','Quando você rolaria dados para curar com magia, use o valor máximo de cada dado.']],
 'Domínio da Luz':[[3,'Magias do Domínio da Luz','Sempre preparadas: Mãos Flamejantes, Fogo das Fadas, Raio Ardente, Ver o Invisível (3); Luz do Dia, Bola de Fogo (5); Olho Arcano, Muralha de Fogo (7); Coluna de Chamas, Vidência (9).'],[3,'Labareda Protetora','Reação: impõe desvantagem num ataque contra você ou criatura a até 9 m. Usos = mod. de Sabedoria por descanso longo.'],[3,'Clarão do Amanhecer','Canalizar Divindade: dissipa escuridão mágica num raio de 9 m, e cada criatura escolhida faz teste de Constituição ou sofre 2d10 + nível de Clérigo de dano Radiante (metade se passar).'],[6,'Labareda Aprimorada','A Labareda Protetora recupera no descanso curto ou longo e dá ao alvo PV temporários (2d6 + mod. de Sabedoria).'],[17,'Auréola de Luz','Ação: por 1 minuto, emite luz plena num raio de 18 m; inimigos nela têm desvantagem em testes contra suas magias de fogo e radiante.']],
 'Domínio da Trapaça':[[3,'Bênção do Trapaceiro','Ação: uma criatura voluntária tem vantagem em Furtividade até você usar de novo ou terminar um descanso longo.'],[3,'Magias do Domínio da Trapaça','Sempre preparadas: Enfeitiçar Pessoa, Disfarçar-se, Invisibilidade, Passar sem Rastro (3); Piscar, Dissipar Magia (5); Porta Dimensional, Polimorfia (7); Modificar Memória, Similaridade (9).'],[3,'Invocar Duplicata','Canalizar Divindade: cria uma ilusão sua por 1 minuto. Você pode conjurar magias como se estivesse no lugar dela e tem vantagem em ataques contra quem estiver a até 1,5 m dela.'],[6,'Transposição do Trapaceiro','Ação bônus: troque de lugar com sua duplicata (até 36 m).'],[17,'Duplicata Aprimorada','A duplicata pode atacar, curar com toque e dá vantagem a aliados próximos.']],
 'Domínio da Guerra':[[3,'Ataque Guiado','Canalizar Divindade: ao errar um ataque (seu ou de um aliado a até 9 m), some +10 ao resultado.'],[3,'Magias do Domínio da Guerra','Sempre preparadas: Arma Abençoada, Escudo da Fé, Arma Espiritual, Aura Mágica de Guerra (3); Manto do Cruzado, Espíritos Guardiões (5); Movimentação Livre, Pele de Pedra (7); Golpe de Chamas, Imobilizar Monstro (9).'],[3,'Sacerdote da Guerra','Depois da ação de Atacar, faça um ataque com arma como ação bônus. Usos = mod. de Sabedoria por descanso curto ou longo.'],[6,'Bênção do Deus da Guerra','Gaste Canalizar Divindade para conjurar Escudo da Fé ou Arma Espiritual sem espaço e sem concentração.'],[17,'Avatar da Batalha','Resistência a dano de concussão, cortante e perfurante.']],
 'Círculo da Terra':[[3,'Magias do Círculo da Terra','Escolha um terreno a cada descanso longo (Árido, Polar, Temperado ou Tropical): ele define magias sempre preparadas nos níveis 3, 5, 7 e 9.'],[3,'Ajuda da Terra','Gaste 1 uso de Forma Selvagem: criaturas num raio de 3 m a até 18 m fazem teste de Constituição ou sofrem 2d6 de dano Necrótico (sobe com o nível), e uma criatura recupera a mesma quantidade em PV.'],[6,'Recuperação Natural','Conjure uma magia do círculo sem gastar espaço, e num descanso curto recupere espaços somando até metade do nível de Druida. Cada uso 1 vez por descanso longo.'],[10,'Proteção da Natureza','Imune a Envenenado e resistência ao dano do seu terreno atual.'],[14,'Santuário da Natureza','Gaste 1 uso de Forma Selvagem: árvores espectrais num cubo de 4,5 m dão meia cobertura a aliados e a resistência do seu terreno, por 1 minuto.']],
 'Círculo da Lua':[[3,'Formas do Círculo','Sua Forma Selvagem pode virar feras com ND igual a um terço do nível de Druida. Na forma, CA = 13 + mod. de Sabedoria se for maior, e ganha PV temporários iguais a 3 × nível de Druida.'],[3,'Magias do Círculo da Lua','Sempre preparadas: Curar Ferimentos, Raio Lunar, Estrelas Cintilantes (3); Conjurar Animais (5); Fonte de Luar (7); Curar Ferimentos em Massa (9). Pode conjurá-las na Forma Selvagem.'],[6,'Golpes Aprimorados','Na Forma Selvagem, seus ataques podem causar dano Radiante e você pode conjurar Raio Lunar como parte da transformação.'],[10,'Passo Lunar','Ação bônus: teletransporte de até 9 m e vantagem no próximo ataque. Usos = mod. de Sabedoria por descanso longo, ou gaste espaço de 2º círculo ou maior.'],[14,'Forma Lunar','Uma vez por turno, um ataque na Forma Selvagem causa 2d10 Radiante extra, e o Passo Lunar pode levar um aliado.']],
 'Círculo do Mar':[[3,'Magias do Círculo do Mar','Sempre preparadas: Névoa Obscurecente, Raio de Gelo, Lufada de Vento, Onda Trovejante (3); Relâmpago, Respirar na Água (5); Controlar a Água, Tempestade de Gelo (7); Conjurar Elemental, Imobilizar Monstro (9).'],[3,'Ira do Mar','Gaste 1 uso de Forma Selvagem: emanação de 1,5 m por 10 minutos. Ao ativar e como ação bônus, uma criatura nela faz teste de Constituição ou sofre dano de Frio (dados de d6 = mod. de Sabedoria) e é empurrada 4,5 m.'],[6,'Afinidade Aquática','O tamanho da Ira do Mar aumenta para 3 m e você ganha deslocamento de natação.'],[10,'Nascido da Tempestade','Com a Ira do Mar ativa, você tem deslocamento de voo e resistência a Frio, Elétrico e Trovejante.'],[14,'Dádiva Oceânica','Você pode manifestar a Ira do Mar em torno de um aliado; gastando 2 usos, ela fica em vocês dois.']],
 'Círculo das Estrelas':[[3,'Mapa Estelar','Você tem um mapa estelar como foco. Sempre conhece Orientação e tem Raio Guiador preparado, podendo conjurá-lo sem espaço (mod. de Sabedoria vezes por descanso longo).'],[3,'Forma Estrelada','Gaste 1 uso de Forma Selvagem: forma luminosa por 10 minutos com uma constelação. Arqueiro: ação bônus, ataque de 1d8 + Sab Radiante. Cálice: ao curar com magia, outra criatura recupera 1d8 + Sab. Dragão: testes de Int e Sab e de concentração tratam 9 ou menos como 10.'],[6,'Presságio Cósmico','Após um descanso longo, role um dado: par = Bem-estar (soma 1d6 a um teste de D20 de aliado), ímpar = Infortúnio (subtrai 1d6 de inimigo). Usos = mod. de Sabedoria.'],[10,'Constelações Cintilantes','Os d8 da Forma Estrelada viram 2d8, o Dragão dá voo de 6 m e você pode trocar de constelação a cada turno.'],[14,'Cheio de Estrelas','Na Forma Estrelada, você tem resistência a dano de concussão, cortante e perfurante.']],
 'Mestre de Batalha':[[3,'Estudante da Guerra','Proficiência com um tipo de ferramenta de artesão e uma perícia da lista do Guerreiro.'],[3,'Superioridade em Combate','Você conhece 3 manobras (mais no 7, 10 e 15) e tem 4 Dados de Superioridade d8 (5 no 7, 6 no 15; d10 no 10, d12 no 18). CD das manobras = 8 + For ou Des + proficiência. Recupera no descanso curto ou longo.'],[7,'Conhecer o Inimigo','Ação bônus: descubra as imunidades, resistências e vulnerabilidades de uma criatura a até 9 m. 1 vez por descanso longo, ou gaste 1 Dado de Superioridade.'],[10,'Superioridade Aprimorada','Seus Dados de Superioridade viram d10 (d12 no nível 18).'],[15,'Implacável','1 vez por turno, ao usar uma manobra sem ter Dados de Superioridade, role 1d8 e use-o no lugar.']],
 'Campeão':[[3,'Crítico Aprimorado','Seus ataques com arma e desarmados acertam crítico com 19 ou 20.'],[3,'Atleta Notável','Vantagem em Iniciativa e testes de Força (Atletismo); após um crítico, mova-se metade do deslocamento sem provocar ataques de oportunidade.'],[7,'Estilo de Luta Adicional','Ganhe mais um talento de Estilo de Luta.'],[10,'Guerreiro Heroico','No início de cada turno em combate, você pode ganhar Inspiração Heroica se não tiver.'],[15,'Crítico Superior','Crítico com 18, 19 ou 20.'],[18,'Sobrevivente','Vantagem em testes contra a morte, e no início do turno, Sangrando, recupera 5 + mod. de Constituição em PV.']],
 'Cavaleiro Arcano':[[3,'Conjuração do Cavaleiro Arcano','Você conjura magias de Mago usando Inteligência (truques e espaços conforme a tabela da subclasse).'],[3,'Arma Vinculada','Ritual de 1 hora com até duas armas: não pode ser desarmado delas e pode invocá-las para a mão como ação bônus.'],[7,'Magia de Guerra','Ao usar a ação de Atacar, troque um dos ataques por um truque.'],[10,'Golpe Místico','Ao acertar uma criatura com arma, ela tem desvantagem no próximo teste de resistência contra uma magia sua até o fim do seu próximo turno.'],[15,'Investida Arcana','Ao usar Surto de Ação, você pode se teletransportar até 9 m.'],[18,'Magia de Guerra Aprimorada','Ao usar a ação de Atacar, troque dois ataques por uma magia de 1º ou 2º círculo.']],
 'Guerreiro Psíquico':[[3,'Poder Psiônico','Dados de Energia Psiônica (2 × bônus de proficiência; d6, d8 no 5, d10 no 11, d12 no 17). Campo Protetor: reação para reduzir dano em um dado + Int. Golpe Psiônico: dano de Força extra de um dado + Int. Movimento Telecinético: mova um objeto ou criatura até 9 m. Recupera 1 dado no descanso curto e todos no longo.'],[7,'Adepto Telecinético','Salto Psi: gaste um dado para ganhar voo por 1 rodada. Empurrão Telecinético: o Golpe Psiônico pode empurrar 3 m ou derrubar.'],[10,'Mente Protegida','Resistência a dano Psíquico; no início do turno, gaste um dado para encerrar Enfeitiçado e Amedrontado.'],[15,'Baluarte de Força','Ação bônus e um dado: até mod. de Inteligência criaturas ganham meia cobertura por 1 minuto.'],[18,'Mestre Telecinético','Você sempre tem Telecinesia preparada e pode conjurá-la sem espaço 1 vez por descanso longo; enquanto se concentra nela, pode atacar como ação bônus.']],
 'Faca da Alma':[[3,'Poder Psiônico da Alma','Dados de Energia Psiônica (2 × bônus de proficiência). Psi-Assistido: ao falhar num teste de atributo, role um dado e some. Sussurros Psíquicos: comunicação telepática com aliados por horas.'],[3,'Lâminas Psíquicas','Ao atacar, crie uma lâmina psíquica (1d6 Psíquico, Acuidade, arremesso 18 m) e, como ação bônus, outra de 1d4.'],[9,'Lâminas da Alma','Golpe Teleguiado: gaste um dado para somar a um ataque com a lâmina que errou. Teletransporte Psíquico: lance a lâmina e teletransporte-se até onde ela cair.'],[13,'Véu Psíquico','Ação: fique Invisível por 1 hora (até causar dano ou forçar teste). 1 vez por descanso longo, ou gaste um dado.'],[17,'Rasgar a Mente','Ao causar dano de Ataque Furtivo com a lâmina, o alvo faz teste de Sabedoria ou fica Atordoado. 1 vez por descanso longo, ou gaste 3 dados.']],
 'Ladrão':[[3,'Mãos Rápidas','A ação bônus de Ação Ardilosa também pode fazer Prestidigitação, usar ferramentas de ladrão ou a ação Usar Objeto.'],[3,'Trabalho de Segundo Andar','Deslocamento de escalada igual ao normal e saltos maiores (usa Destreza).'],[9,'Furtividade Suprema','Você ganha a opção Ataque Furtivo "Ataque Furtivo Sorrateiro" e mantém a condição Invisível ao atacar escondido.'],[13,'Usar Item Mágico','Pode usar qualquer item mágico ignorando requisitos de classe e espécie, com até 4 sintonizações; varinhas têm chance de não gastar carga.'],[17,'Reflexos de Ladrão','No primeiro turno de cada combate, você joga dois turnos: um na sua Iniciativa e outro com Iniciativa − 10.']],
 'Assassino':[[3,'Assassinar','Vantagem na Iniciativa e, na primeira rodada, vantagem contra quem ainda não agiu; o Ataque Furtivo causa dano extra igual ao nível de Ladino.'],[3,'Ferramentas do Assassino','Proficiência com kit de disfarce e kit de envenenador.'],[9,'Especialista em Infiltração','Pode criar identidades falsas e imitar falas e escrita de outras pessoas.'],[13,'Armas Envenenadas','Ao usar a opção Veneno do Ataque Furtivo, o alvo também sofre 2d6 de dano de Veneno.'],[17,'Golpe Mortal','Ao acertar Ataque Furtivo na primeira rodada, o alvo faz teste de Constituição ou o dano do ataque dobra.']],
 'Trapaceiro Arcano':[[3,'Conjuração do Trapaceiro Arcano','Você conjura magias de Mago usando Inteligência.'],[3,'Mão Mágica Prestidigitadora','Sua Mão Mágica é invisível e pode guardar ou pegar objetos, usar ferramentas de ladrão à distância.'],[9,'Emboscada Mágica','Se estiver escondido ao conjurar uma magia, o alvo tem desvantagem no teste de resistência.'],[13,'Trapaceiro Versátil','Ação bônus: use a Mão Mágica para distrair, ganhando vantagem nos ataques contra uma criatura a até 1,5 m dela.'],[17,'Ladrão de Magia','Reação: quando uma criatura conjura uma magia contra você, ela faz teste de Inteligência; se falhar, a magia é anulada e você aprende a magia por 8 horas.']],
 'Guerreiro da Misericórdia':[[3,'Mão Curativa','Ao usar Rajada de Golpes, troque um golpe por cura: 1 dado de Artes Marciais + mod. de Sabedoria (gasta 1 Foco).'],[3,'Mão Nociva','1 vez por turno, ao acertar um ataque desarmado, gaste 1 Foco para causar dano Necrótico extra (dado de Artes Marciais + Sab) e Envenenar o alvo.'],[3,'Implementos da Misericórdia','Proficiência em Intuição, Medicina e kit de herbalismo.'],[6,'Toque do Médico','A Mão Curativa também encerra uma doença ou condição (Cego, Surdo, Paralisado, Envenenado, Atordoado); a Mão Nociva também deixa Envenenado.'],[11,'Rajada de Cura e Dano','Na Rajada de Golpes, troque golpes por Mão Curativa sem gastar Foco, e aplique Mão Nociva sem Foco. Usos = mod. de Sabedoria por descanso longo.'],[17,'Mão da Misericórdia Final','Toque uma criatura que morreu nas últimas 24 horas e gaste 5 Foco: ela volta com 4d10 + Sab em PV. 1 vez por descanso longo.']],
 'Guerreiro da Sombra':[[3,'Artes da Sombra','Gaste 1 Foco para conjurar Escuridão sem componentes; você enxerga através dela. Também conhece o truque Ilusão Menor.'],[6,'Passo das Sombras','Ação bônus: estando em penumbra ou escuridão, teletransporte-se até 18 m para outra área escura e tenha vantagem no próximo ataque corpo a corpo.'],[11,'Passo Aprimorado','Pode gastar 1 Foco para usar o Passo das Sombras de qualquer lugar e fazer um ataque desarmado depois.'],[17,'Manto das Sombras','Ação e 3 Foco: por 1 minuto, fica Invisível em penumbra e escuridão, atravessa criaturas e objetos e pode usar Rajada de Golpes sem gastar Foco.']],
 'Guerreiro dos Elementos':[[3,'Sintonia Elemental','Gaste 1 Foco: por 10 minutos, seu alcance desarmado aumenta 3 m e seus golpes podem causar dano de Ácido, Frio, Fogo, Elétrico ou Trovejante, e empurrar ou puxar 3 m.'],[3,'Manipular Elementos','Você conhece o truque Elementalismo.'],[6,'Explosão Elemental','Ação e 2 Foco: esfera de 6 m a até 36 m; cada criatura faz teste de Destreza ou sofre 3 dados de Artes Marciais do tipo escolhido.'],[11,'Passos dos Elementos','Com a Sintonia ativa, você tem deslocamento de voo e natação.'],[17,'Epítome Elemental','Com a Sintonia ativa: resistência ao tipo escolhido, Passo do Vento causa dano a quem você passa, e 1 vez por turno um golpe causa dano extra do tipo.']],
 'Guerreiro da Mão Aberta':[[3,'Técnica da Mão Aberta','Ao acertar um golpe da Rajada de Golpes: o alvo não pode fazer ataques de oportunidade até seu próximo turno, ou é empurrado 4,5 m (teste de Força), ou fica Caído (teste de Destreza).'],[6,'Integridade do Corpo','Ação bônus: role o dado de Artes Marciais e recupere PV iguais ao resultado + mod. de Sabedoria. Usos = mod. de Sabedoria por descanso longo.'],[11,'Passo Veloz','Quando você usa uma ação bônus que não seja Passo do Vento, pode usar Passo do Vento logo em seguida.'],[17,'Palma Vibrante','Gaste 4 Foco ao acertar um golpe: depois, como ação, o alvo faz teste de Constituição ou sofre 10d12 de dano de Força (metade se passar).']],
 'Juramento de Devoção':[[3,'Magias do Juramento de Devoção','Sempre preparadas: Proteção contra o Bem e o Mal, Escudo da Fé (3); Auxílio, Zona da Verdade (5); Sinal de Esperança, Dissipar Magia (9); Movimentação Livre, Guardião da Fé (13); Comunhão, Coluna de Chamas (17).'],[3,'Arma Sagrada','Canalizar Divindade: por 10 minutos, uma arma emite luz, soma mod. de Carisma aos ataques e pode causar dano Radiante.'],[7,'Aura de Devoção','Você e aliados na sua Aura de Proteção são imunes a Enfeitiçado.'],[15,'Castigo Protetor','Ao usar Castigo Divino, você e aliados na sua aura ganham meia cobertura até o início do seu próximo turno.'],[20,'Auréola Sagrada','Ação bônus: por 10 minutos, aura de luz que causa dano Radiante a inimigos e dá vantagem em resistência contra Corruptores e Mortos-Vivos. 1 vez por descanso longo, ou gaste espaço de 5º círculo.']],
 'Juramento de Glória':[[3,'Magias do Juramento de Glória','Sempre preparadas: Proteção contra o Bem e o Mal, Heroísmo (3); Aprimorar Atributo, Arma Mágica (5); Velocidade, Proteção contra Energia (9); Compulsão, Movimentação Livre (13); Lenda, Destruição em Círculo (17).'],[3,'Atleta Inigualável','Canalizar Divindade: por 1 hora, vantagem em Atletismo e Acrobacia e saltos maiores.'],[3,'Castigo Inspirador','Depois de usar Castigo Divino, gaste Canalizar Divindade para distribuir PV temporários (2d8 + nível de Paladino) entre criaturas a até 9 m.'],[7,'Aura de Rapidez','Seu deslocamento aumenta 3 m, e aliados que começam o turno na aura ganham +3 m.'],[15,'Defesa Gloriosa','Reação: some o mod. de Carisma à CA de uma criatura contra um ataque; se errar, você ataca o atacante. Usos = mod. de Carisma por descanso longo.'],[20,'Lenda Viva','Ação bônus, 10 minutos: vantagem em testes de Carisma, 1 vez por turno um ataque que erra acerta, e rerrola resistências que falhar. 1 vez por descanso longo, ou espaço de 5º círculo.']],
 'Juramento dos Anciões':[[3,'Magias do Juramento dos Anciões','Sempre preparadas: Golpe Constritor, Falar com Animais (3); Raio Lunar, Passo Nebuloso (5); Crescimento de Plantas, Proteção contra Energia (9); Tempestade de Gelo, Pele de Pedra (13); Comunhão com a Natureza, Caminhar em Árvores (17).'],[3,'Ira da Natureza','Canalizar Divindade: vinhas espectrais a até 4,5 m; criaturas escolhidas fazem teste de Força ou ficam Contidas por 1 minuto.'],[7,'Aura de Proteção Ancestral','Você e aliados na aura têm resistência a dano Necrótico, Psíquico e Radiante.'],[15,'Sentinela Imortal','Ao cair a 0 PV sem morrer, fique com PV igual a 3 × nível de Paladino. 1 vez por descanso longo. Você também não envelhece magicamente.'],[20,'Campeão Ancestral','Ação bônus, 1 minuto: regenera 10 PV por turno, conjura magias de Paladino de 1 ação como ação bônus e inimigos na aura têm desvantagem contra suas magias. 1 vez por descanso longo, ou espaço de 5º círculo.']],
 'Juramento de Vingança':[[3,'Magias do Juramento de Vingança','Sempre preparadas: Perdição, Marca do Caçador (3); Imobilizar Pessoa, Passo Nebuloso (5); Velocidade, Proteção contra Energia (9); Banimento, Porta Dimensional (13); Imobilizar Monstro, Vidência (17).'],[3,'Voto de Inimizade','Ao usar a ação de Atacar, gaste Canalizar Divindade: vantagem nos ataques contra uma criatura a até 9 m por 1 minuto.'],[7,'Vingador Implacável','Ao acertar um ataque de oportunidade, reduza o deslocamento do alvo a 0 e mova-se metade do seu sem provocar ataques.'],[15,'Alma de Vingança','Quando a criatura do seu Voto ataca, você pode usar a reação para atacá-la.'],[20,'Anjo Vingador','Ação bônus, 10 minutos: voo de 18 m e aura que deixa inimigos Amedrontados (teste de Sabedoria). 1 vez por descanso longo, ou espaço de 5º círculo.']],
 'Mestre das Feras':[[3,'Companheiro Primal','Você invoca uma Fera Primal (da Terra, do Mar ou do Céu) que age no seu turno; como ação bônus, você ordena que ela ataque. Se morrer, pode trazê-la de volta gastando um espaço de magia.'],[7,'Treinamento Excepcional','A fera pode usar Disparada, Desengajar, Esquivar ou Ajudar como ação bônus, e seus ataques podem causar dano de Força.'],[11,'Fúria Bestial','A fera ataca duas vezes quando você ordena, e um ataque pode aplicar sua Marca do Caçador.'],[15,'Compartilhar Magias','Magias que você conjura em si podem afetar também sua fera a até 9 m.']],
 'Andarilho Feérico':[[3,'Golpes Terríveis','1 vez por turno, ao acertar com arma, cause 1d4 de dano Psíquico extra (1d6 no nível 11).'],[3,'Magias do Andarilho Feérico','Sempre preparadas: Enfeitiçar Pessoa (3), Passo Nebuloso (5), Convocar Feérico (9), Porta Dimensional (13), Despertar (17).'],[3,'Encanto Sobrenatural','Proficiência em uma perícia entre Enganação, Atuação ou Persuasão, e bônus de Sabedoria em testes de Carisma.'],[7,'Torção Sedutora','Vantagem contra Enfeitiçado e Amedrontado; quando uma criatura passa num teste desses contra você, use a reação para tentar Enfeitiçá-la ou Amedrontá-la.'],[11,'Reforços Feéricos','Conjure Convocar Feérico sem espaço 1 vez por descanso longo, e sem componente material.'],[15,'Andarilho Nebuloso','Conjure Passo Nebuloso sem espaço (mod. de Sabedoria vezes por descanso longo) e leve um aliado junto.']],
 'Espreitador Sombrio':[[3,'Emboscada Terrível','Soma mod. de Sabedoria à Iniciativa, +3 m de deslocamento no primeiro turno, e Golpe Terrível: ao acertar, cause 2d6 Psíquico extra (mod. de Sabedoria vezes por descanso longo).'],[3,'Magias do Espreitador Sombrio','Sempre preparadas: Disfarçar-se (3), Truque de Corda (5), Medo (9), Invisibilidade Maior (13), Aparência Falsa (17).'],[3,'Visão Umbral','Visão no escuro de 18 m (ou +18 m) e, na escuridão, você fica Invisível para quem depende de visão no escuro.'],[7,'Mente de Ferro','Proficiência em testes de resistência de Sabedoria (ou Inteligência/Carisma, se já tiver).'],[11,'Rajada do Perseguidor','O Golpe Terrível passa a causar 2d8 e pode afetar também outra criatura próxima, ou deixá-la Amedrontada.'],[15,'Esquiva Sombria','Reação: quando uma criatura faz ataque contra você, imponha desvantagem e teletransporte-se até 9 m.']],
 'Caçador':[[3,'Conhecimento do Caçador','Ao usar Marca do Caçador, você descobre imunidades, resistências e vulnerabilidades do alvo.'],[3,'Presa do Caçador','Escolha uma opção (pode trocar no descanso): Matador de Colossos (1d8 extra contra alvo já ferido, 1 vez por turno) ou Destruidor de Hordas (ataque extra contra outra criatura a até 1,5 m do alvo, 1 vez por turno).'],[7,'Táticas Defensivas','Escolha: Escapar da Horda (ataques de oportunidade contra você têm desvantagem) ou Defesa Multiataque (após ser atingido, +4 de CA contra o mesmo atacante no turno).'],[11,'Presa Superior','1 vez por turno, ao causar dano ao alvo da Marca do Caçador, cause o dano extra da Marca também a outra criatura a até 9 m.'],[15,'Defesa Superior','Reação: ao sofrer dano, ganhe resistência a esse dano neste turno.']],
 'Feitiçaria Aberrante':[[3,'Magias Psiônicas','Sempre preparadas: Braços de Hadar, Sussurros Dissonantes, Explosão Mental (3); Fome de Hadar, Enviar Mensagem (5); Tentáculos Negros de Evard, Invocar Aberração (7); Elo Telepático de Rary, Telecinesia (9). Pode conjurá-las sem componentes verbais/somáticos.'],[3,'Fala Telepática','Ação bônus: elo telepático com uma criatura a até 9 m por minutos iguais ao nível de Feiticeiro.'],[6,'Feitiçaria Psiônica','Conjure suas Magias Psiônicas gastando Pontos de Feitiçaria iguais ao círculo, sem componentes.'],[6,'Defesas Psíquicas','Resistência a dano Psíquico e vantagem contra Enfeitiçado e Amedrontado.'],[14,'Revelação na Carne','Gaste 1 ou mais Pontos de Feitiçaria: ganhe por 10 minutos visão verdadeira, voo, natação e respirar na água, ou se espremer por espaços apertados.'],[18,'Implosão Distorcida','Ação: teletransporte-se até 36 m e puxe criaturas próximas ao ponto de partida, causando 3d10 de Força. 1 vez por descanso longo, ou 5 Pontos de Feitiçaria.']],
 'Feitiçaria Mecânica':[[3,'Magias Mecânicas','Sempre preparadas: Auxílio, Alarme, Restauração Menor, Proteção contra o Bem e o Mal (3); Dissipar Magia, Proteção contra Energia (5); Movimentação Livre, Convocar Constructo (7); Muralha de Força, Restauração Maior (9).'],[3,'Restaurar o Equilíbrio','Reação: anule vantagem ou desvantagem num teste de D20 de uma criatura a até 18 m. Usos = mod. de Carisma por descanso longo.'],[6,'Bastião da Lei','Ação e 1 a 5 Pontos de Feitiçaria: proteção de d8 (um por ponto) que reduz dano sofrido por uma criatura.'],[14,'Transe da Ordem','Ação bônus, 1 minuto: ataques contra você não têm vantagem e seus d20 abaixo de 10 contam como 10. 1 vez por descanso longo, ou 5 Pontos de Feitiçaria.'],[18,'Cavalgada Mecânica','Ação: cubo de 9 m onde você cura até 100 PV divididos, conserta objetos e encerra magias de 6º círculo ou menor. 1 vez por descanso longo, ou 7 Pontos de Feitiçaria.']],
 'Feitiçaria Dracônica':[[3,'Resiliência Dracônica','Seus PV máximos aumentam em 1 por nível de Feiticeiro, e sem armadura sua CA é 10 + Des + Car.'],[3,'Magias Dracônicas','Sempre preparadas: Alterar-se, Orbe Cromático, Comando, Sopro do Dragão (3); Medo, Voar (5); Olho Arcano, Enfeitiçar Monstro (7); Lendas Folclóricas, Invocar Dragão (9).'],[6,'Afinidade Elemental','Escolha Ácido, Frio, Fogo, Elétrico ou Veneno: resistência a ele e some o mod. de Carisma ao dano de magias desse tipo.'],[14,'Asas de Dragão','Ação bônus: asas por 1 hora, voo de 18 m. 1 vez por descanso longo, ou 3 Pontos de Feitiçaria.'],[18,'Companheiro Dracônico','Conjure Invocar Dragão sem espaço e sem concentração (1 minuto) 1 vez por descanso longo.']],
 'Feitiçaria da Magia Selvagem':[[3,'Surto de Magia Selvagem','1 vez por turno, ao conjurar uma magia com espaço, role d20; com 20, role na tabela de Surto de Magia Selvagem.'],[3,'Marés do Caos','Vantagem num teste de D20. Volta no descanso longo ou depois de um Surto.'],[6,'Distorcer a Sorte','Reação e 1 Ponto de Feitiçaria: some ou subtraia 1d4 do teste de D20 de outra criatura.'],[14,'Caos Controlado','Ao rolar na tabela de Surto, role duas vezes e escolha.'],[18,'Surto Domado','Ao conjurar com espaço, você pode escolher um efeito da tabela de Surto em vez de rolar (1 vez por descanso longo).']],
 'Patrono Arquifada':[[3,'Magias da Arquifada','Sempre preparadas: Calmaria, Fogo das Fadas, Passo Nebuloso, Força Fantasmagórica, Sono (3); Piscar, Crescimento de Plantas (5); Dominar Fera, Invisibilidade Maior (7); Dominar Pessoa, Similaridade (9).'],[3,'Passos da Fada','Conjure Passo Nebuloso sem espaço (mod. de Carisma vezes por descanso longo), com um efeito extra: Revigorante (PV temporários a um aliado) ou Provocante (inimigos fazem teste de Sabedoria ou têm desvantagem contra outros).'],[6,'Fuga Nebulosa','Conjure Passo Nebuloso como reação ao sofrer dano; novos efeitos: Desaparecer (Invisível) ou Terrível (dano Psíquico em quem estava perto).'],[10,'Defesas Sedutoras','Imune a Enfeitiçado; quando alguém tenta Enfeitiçar você, use a reação para devolver o efeito.'],[14,'Magia Feiticeira','Depois de conjurar uma magia de encantamento ou ilusão, conjure Passo Nebuloso sem espaço.']],
 'Patrono Celestial':[[3,'Magias do Celestial','Sempre preparadas: Auxílio, Curar Ferimentos, Raio Guiador, Restauração Menor, Luz, Chama Sagrada (3); Luz do Dia, Revivificar (5); Guardião da Fé, Muralha de Fogo (7); Golpe de Chamas, Invocar Celestial (9).'],[3,'Luz Curativa','Reserva de d6 igual a 1 + nível de Bruxo. Ação bônus: gaste até mod. de Carisma dados para curar uma criatura a até 18 m.'],[6,'Alma Radiante','Resistência a dano Radiante; 1 vez por turno, quando uma magia causa Fogo ou Radiante, some o mod. de Carisma ao dano.'],[10,'Resiliência Celestial','Ao terminar um descanso ou usar Astúcia Mágica, você ganha PV temporários (nível de Bruxo + Car) e aliados também.'],[14,'Vingança Abrasadora','Quando você ou um aliado faria um teste contra a morte, ele volta com metade dos PV e inimigos a até 9 m sofrem 2d8 + Car Radiante e ficam Cegos. 1 vez por descanso longo.']],
 'Patrono Corruptor':[[3,'Magias do Corruptor','Sempre preparadas: Mãos Flamejantes, Comando, Cegueira/Surdez, Raio Ardente (3); Bola de Fogo, Névoa Fétida (5); Escudo de Fogo, Muralha de Fogo (7); Missão, Praga (9).'],[3,'Bênção do Sombrio','Ao reduzir um inimigo a 0 PV (ou quando alguém próximo o faz), ganhe PV temporários iguais a Car + nível de Bruxo.'],[6,'Sorte do Sombrio','Some 1d10 a um teste de atributo ou de resistência. Usos = mod. de Carisma por descanso longo.'],[10,'Resiliência Infernal','Após um descanso, escolha um tipo de dano (exceto Força) para ter resistência.'],[14,'Lançar no Inferno','1 vez por turno, ao acertar um ataque, o alvo faz teste de Carisma ou é levado aos planos inferiores, sofre 8d10 Psíquico e fica Incapacitado. 1 vez por descanso longo, ou espaço de Pacto.']],
 'Patrono Grande Antigo':[[3,'Mente Desperta','Ação bônus: elo telepático com uma criatura a até 9 m por minutos iguais ao nível de Bruxo.'],[3,'Magias do Grande Antigo','Sempre preparadas: Sussurros Dissonantes, Riso Histérico, Detectar Pensamentos, Força Fantasmagórica (3); Clarividência, Fome de Hadar (5); Confusão, Tentáculos Negros (7); Modificar Memória, Telecinesia (9).'],[3,'Feitiços Psíquicos','Magias de encantamento e ilusão de Bruxo podem ser conjuradas sem componentes, e seu dano pode virar Psíquico.'],[6,'Combatente Clarividente','Ao criar o elo da Mente Desperta, a criatura faz teste de Sabedoria; se falhar, tem desvantagem contra você e você vantagem contra ela por 1 minuto. 1 vez por descanso curto ou longo, ou espaço de Pacto.'],[10,'Escudo Mental','Resistência a dano Psíquico, seus pensamentos não podem ser lidos e, quando alguém causa Psíquico a você, sofre o mesmo dano.'],[14,'Criar Servo','Você sempre tem Invocar Aberração preparada. Ao conjurá-la, ela não exige concentração (dura 1 minuto), ganha PV temporários e seus ataques causam dano Psíquico extra.']],
 'Abjurador':[[3,'Sábio da Abjuração','Copiar magias de abjuração para o grimório custa metade do tempo e do ouro.'],[3,'Proteção Arcana','Ao conjurar uma magia de abjuração com espaço, crie uma proteção com PV = 2 × nível de Mago + Int. Ela absorve dano antes de você; conjurar abjurações recupera 2 PV por círculo.'],[6,'Proteção Projetada','Reação: quando uma criatura a até 9 m sofre dano, sua Proteção Arcana absorve esse dano.'],[10,'Rompedor de Magias','Você sempre tem Contramágica e Dissipar Magia preparadas; ao usá-las, soma proficiência ao teste e não gasta o espaço se falhar.'],[14,'Resistência Mágica','Vantagem em testes de resistência contra magias e resistência ao dano delas.']],
 'Adivinho':[[3,'Sábio da Adivinhação','Copiar magias de adivinhação custa metade do tempo e do ouro.'],[3,'Portento','Após um descanso longo, role 2d20 (3 no nível 14) e anote. Troque qualquer teste de D20 visível por um desses valores.'],[6,'Adivinhação Especializada','Ao conjurar uma adivinhação de 2º círculo ou maior, recupere um espaço de círculo menor.'],[10,'O Terceiro Olho','Ação bônus: ganhe visão no escuro, ver o Etéreo, ler qualquer idioma ou ver o invisível até o próximo descanso.'],[14,'Portento Maior','Você rola três d20 para o Portento.']],
 'Evocador':[[3,'Sábio da Evocação','Copiar magias de evocação custa metade do tempo e do ouro. Você também aprende um truque de evocação.'],[3,'Truque Potente','Quando uma criatura passa no teste contra seu truque, ainda sofre metade do dano.'],[6,'Esculpir Magias','Ao conjurar evocação que afeta área, escolha criaturas (1 + círculo) que passam automaticamente e não sofrem dano.'],[10,'Evocação Potencializada','Some o mod. de Inteligência a uma rolagem de dano das suas magias de evocação.'],[14,'Sobrecarga','Ao conjurar uma magia de 1º a 5º círculo que causa dano, cause o dano máximo. Repetir antes do descanso longo causa dano Necrótico em você.']],
 'Ilusionista':[[3,'Sábio da Ilusão','Copiar magias de ilusão custa metade do tempo e do ouro.'],[3,'Ilusões Aprimoradas','Conjure ilusões sem componente verbal, alcance aumentado em 18 m, e conheça o truque Ilusão Menor (que pode criar som e imagem juntos).'],[6,'Criaturas Fantasmagóricas','Você sempre tem Convocar Fera e Convocar Feérico preparadas; 1 vez por descanso longo cada uma sem espaço, e as criaturas são ilusões com metade dos PV.'],[10,'Eu Ilusório','Reação: um ataque contra você erra automaticamente. 1 vez por descanso curto ou longo, ou espaço de 2º círculo ou maior.'],[14,'Realidade Ilusória','Ao conjurar uma ilusão com espaço, torne real um objeto não mágico dela por 1 minuto.']]
};
